  const renderTechPortal = () => {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitSuccess, setSubmitSuccess] = useState(false);
    const [submitError, setSubmitError] = useState(null);

    const handleSubmitTechReport = async (e) => {
      e.preventDefault();
      setIsSubmitting(true);
      setSubmitError(null);

      try {
        // Add to Firestore
        const reportData = {
          panelId: techFormData.panelId,
          type: techFormData.inspectionType,
          technicianName: "Tech User", // This would come from user profile
          notes: techFormData.notes,
          status: 'pending',
          timestamp: new Date(),
        };

        // Save to Firestore
        const docRef = await addDoc(collection(db, 'maintenance_records'), reportData);

        // Add to local state too
        addMaintenanceRecord({
          id: docRef.id,
          ...reportData
        });

        // Reset form
        setTechFormData({
          panelId: '',
          inspectionType: 'Routine Check',
          notes: ''
        });

        setSubmitSuccess(true);
        setTimeout(() => {
          setSubmitSuccess(false);
        }, 3000);

      } catch (error) {
        console.error('Error submitting report:', error);
        setSubmitError('Failed to submit report. Please try again.');
      } finally {
        setIsSubmitting(false);
      }
    };

    return (
      <div className="tech-portal">
        <h2>Technician Portal</h2>
        <p>Submit inspection reports for solar panels.</p>

        {submitSuccess && (
          <div className="success-message">
            Report submitted successfully! The record has been added to maintenance history.
          </div>
        )}

        {submitError && (
          <div className="error-message">{submitError}</div>
        )}

        <form className="inspection-form" onSubmit={handleSubmitTechReport}>
          <div className="form-group">
            <label>Panel ID</label>
            <input 
              type="text" 
              placeholder="Enter Panel ID"
              value={techFormData.panelId}
              onChange={(e) => setTechFormData({...techFormData, panelId: e.target.value})}
              required
            />
          </div>
          <div className="form-group">
            <label>Inspection Type</label>
            <select
              value={techFormData.inspectionType}
              onChange={(e) => setTechFormData({...techFormData, inspectionType: e.target.value})}
            >
              <option>Routine Check</option>
              <option>Maintenance</option>
              <option>Repair</option>
              <option>Emergency Service</option>
            </select>
          </div>
          <div className="form-group">
            <label>Notes</label>
            <textarea 
              placeholder="Enter inspection details"
              value={techFormData.notes}
              onChange={(e) => setTechFormData({...techFormData, notes: e.target.value})}
              required
            ></textarea>
          </div>
          <div className="form-actions">
            <button 
              type="submit" 
              className="submit-btn"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Submitting...' : 'Submit Report'}
            </button>
            <button 
              type="button" 
              className="clear-btn" 
              onClick={() => setTechFormData({
                panelId: '',
                inspectionType: 'Routine Check',
                notes: ''
              })}
              disabled={isSubmitting}
            >
              Clear Form
            </button>
          </div>
        </form>
      </div>
    );
  };

  const renderMaintenanceHistory = () => {
    const [statusFilter, setStatusFilter] = useState('all');
    const [typeFilter, setTypeFilter] = useState('all');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const filteredHistory = maintenanceHistory.filter(record => {
      // Status filter
      if (statusFilter !== 'all' && record.status !== statusFilter) {
        return false;
      }

      // Type filter (if exists in record)
      if (typeFilter !== 'all' && record.type && record.type !== typeFilter) {
        return false;
      }

      // Date filter
      if (startDate && record.timestamp) {
        const recordDate = record.timestamp instanceof Date 
          ? record.timestamp 
          : new Date(record.timestamp.seconds * 1000);

        const filterStartDate = new Date(startDate);
        if (recordDate < filterStartDate) {
          return false;
        }
      }

      if (endDate && record.timestamp) {
        const recordDate = record.timestamp instanceof Date 
          ? record.timestamp 
          : new Date(record.timestamp.seconds * 1000);

        const filterEndDate = new Date(endDate);
        filterEndDate.setHours(23, 59, 59);
        if (recordDate > filterEndDate) {
          return false;
        }
      }

      return true;
    });

    // Helper function to format timestamp
    const formatDate = (timestamp) => {
      if (!timestamp) return 'N/A';

      const date = timestamp instanceof Date 
        ? timestamp 
        : new Date(timestamp.seconds * 1000);

      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    };

    return (
      <div className="maintenance-history">
        <h2>Maintenance History</h2>
        <p>View and filter maintenance records from the database.</p>

        <div className="history-filters">
          <select 
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            <option value="all">All Statuses</option>
            <option value="completed">Completed</option>
            <option value="pending">Pending</option>
            <option value="in-progress">In Progress</option>
          </select>

          <select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
          >
            <option value="all">All Types</option>
            <option value="Routine Check">Routine Check</option>
            <option value="Maintenance">Maintenance</option>
            <option value="Repair">Repair</option>
            <option value="Emergency">Emergency</option>
          </select>

          <div className="date-range">
            <input 
              type="date" 
              placeholder="Start Date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
            />
            <input 
              type="date" 
              placeholder="End Date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
            />
          </div>
        </div>

        {filteredHistory.length === 0 ? (
          <div className="no-records">
            <p>No maintenance records found.</p>
          </div>
        ) : (
          <table className="history-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Panel ID</th>
                <th>Technician</th>
                <th>Efficiency</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredHistory.map((record) => (
                <tr key={record.id}>
                  <td>{formatDate(record.timestamp)}</td>
                  <td>{record.panelId}</td>
                  <td>{record.technicianName}</td>
                  <td>{record.efficiency}%</td>
                  <td>
                    <span className={`status-badge ${record.status}`}>
                      {record.status}
                    </span>
                  </td>
                  <td>
                    <button 
                      className="view-btn"
                      onClick={() => {
                        // View record details
                        console.log('View record:', record);
                      }}
                    >
                      View
                    </button>
                    <button 
                      className="edit-btn"
                      onClick={() => {
                        // Edit record
                        console.log('Edit record:', record);
                      }}
                    >
                      Edit
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    );
  };

  const renderAdminPanel = () => (
    <div className="admin-panel">
      <h2>Admin Panel</h2>
      <div className="admin-stats">
        <div className="stat-card">
          <h3>Total Inspections</h3>
